css:
button {
  font-size: 17px;
  padding: 1em 2.7em;
  font-weight: 500;
  background: rgb(0,71,157);
  background: linear-gradient(90deg, rgba(0,71,157,1) 0%, rgba(23,178,255,1) 100%);
  color: #000;
  font-weight: 900;
  border: none;
  position: relative;
  overflow: hidden;
  border-radius: 0.6em;
  box-shadow: 0 0 10px #7f7f7f;
  transition: 0.2s;
}

.label {
  position: relative;
  top: -1px;
}

.transition {
  transition-timing-function: cubic-bezier(0.8, 0, 0.2, 1);
  transition-duration: 400ms;
  background: #ffffff;
  border-radius: 9999px;
  width: 10em;
  height: 10em;
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
}

button:hover .transition {
  width: 0;
  height: 0;
}

button:hover {
  transition: 0.2s;
  color: #fff;
}

button:active {
  transform: scale(0.97);
}
